import math
        import random
        import time

        LANGUAGE_WRAPPER = 'In a math contest, {alpha} observers stand at the vertices of a regular {alpha}-gon inscribed in a circle. For each observer i, you may choose a clockwise viewing angle theta_i (in degrees), with 0 <= theta_i <= {cap_deg}. The viewing sector for observer i is a wedge of angle theta_i whose bisector is aligned with the clockwise tangent at i; observer i sees exactly those other vertices lying strictly within that clockwise arc (including points exactly on the wedge boundaries). Let a_i be the number of other observers seen by observer i. Subject to the global budget constraint sum_{i=1}^{alpha} theta_i <= {budget_deg}, determine the maximum possible value of sum_{i=1}^{alpha} a_i.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # Choose alpha (number of observers / vertices)
    # We keep alpha moderate to ensure nontrivial integer intervals for budgets.
    for _ in range(1000):
        alpha = rng.randint(60, 240)  # reasonably large
        cap_deg = rng.randint(100, 179)  # strictly less than 180, and not too small
        # Compute per-observer cap on count: k_max = floor(cap_deg * alpha / 360)
        k_max = (cap_deg * alpha) // 360
        if k_max < 2:
            continue  # too trivial per-observer cap
        # We will choose an integer S representing the target total number of increments
        # Each increment costs exactly 360/alpha degrees of budget and adds 1 to sum of a_i
        # The absolute maximum increments from caps is alpha * k_max; choose S below that.
        max_increments = alpha * k_max
        # Make sure we don't trivially saturate caps and don't make it tiny
        S_lo = max(2, alpha // 3)  # avoid tiny sums
        S_hi = max_increments - rng.randint(2, max(2, alpha // 4))  # ensure room below cap
        if S_hi <= S_lo:
            continue
        S = rng.randint(S_lo, S_hi)
        # We need an integer budget_deg such that floor(budget_deg * alpha / 360) = S.
        # The interval for budget_deg is [S * (360/alpha), (S+1) * (360/alpha))
        delta = 360.0 / alpha
        lower = math.ceil(S * delta)
        upper = math.floor((S + 1) * delta - 1e-9)
        if lower > upper:
            continue  # no integer in interval; retry
        budget_deg = rng.randint(lower, upper)
        # Safety: enforce budget not exceeding total per-observer caps
        # sum theta_i <= alpha * cap_deg
        if budget_deg > alpha * cap_deg:
            # Reduce budget if needed to respect global cap (rare but safe guard)
            budget_deg = alpha * cap_deg
            # Recompute S from this budget
            S = (budget_deg * alpha) // 360
            if S < 2:
                continue
        return {
            'alpha': alpha,
            'cap_deg': cap_deg,
            'budget_deg': budget_deg
        }
    # Fallback deterministic values if random attempts fail
    alpha = 120
    cap_deg = 150
    k_max = (cap_deg * alpha) // 360
    S = alpha * k_max - 10
    delta = 360.0 / alpha
    lower = math.ceil(S * delta)
    upper = math.floor((S + 1) * delta - 1e-9)
    budget_deg = max(lower, min(upper, alpha * cap_deg))
    return {'alpha': alpha, 'cap_deg': cap_deg, 'budget_deg': budget_deg}

        def verifier(assign):
    # Validate types and domain
    try:
        alpha = int(assign.get('alpha'))
        cap_deg = int(assign.get('cap_deg'))
        budget_deg = int(assign.get('budget_deg'))
    except Exception:
        # invalid types
        return (False, None)  # invalid assignment
    # Basic domain checks
    if alpha < 3:
        # need at least a triangle
        return (False, None)
    if not (0 <= cap_deg < 180):
        return (False, None)
    if budget_deg < 0:
        return (False, None)
    # Global budget cannot exceed sum of per-observer caps
    if budget_deg > alpha * cap_deg:
        return (False, None)
    # Compute per-observer cap on the number of seen neighbors
    k_max = (cap_deg * alpha) // 360  # floor(cap_deg * alpha / 360)
    # Difficulty guard: avoid trivial cases
    if k_max < 2:
        return (False, None)
    # Compute budget-limited total increments
    S_budget = (budget_deg * alpha) // 360
    # The achievable maximum total sum is the minimum of the budget-limited increments
    # and the cap-limited increments over all observers.
    answer = min(S_budget, alpha * k_max)
    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

